-- Initial Cloudflare D1 schema for Job Tracker.
-- IDs are UUID strings generated by the Worker.
-- Timestamps are stored as UTC ISO-8601 strings.

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY NOT NULL,
    email TEXT NOT NULL COLLATE NOCASE UNIQUE,
    password_hash TEXT NOT NULL,
    full_name TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE IF NOT EXISTS applications (
    id TEXT PRIMARY KEY NOT NULL,
    user_id TEXT NOT NULL,
    company TEXT NOT NULL,
    job_title TEXT NOT NULL,
    location TEXT,
    job_url TEXT,
    salary TEXT,
    source TEXT,
    status TEXT NOT NULL DEFAULT 'SAVED'
        CHECK (status IN ('SAVED', 'APPLIED', 'SCREENING', 'INTERVIEW', 'OFFER', 'ACCEPTED', 'REJECTED', 'WITHDRAWN')),
    applied_date TEXT,
    closing_date TEXT,
    description TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_applications_user_updated
    ON applications(user_id, updated_at DESC);

CREATE INDEX IF NOT EXISTS idx_applications_user_status_updated
    ON applications(user_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS interviews (
    id TEXT PRIMARY KEY NOT NULL,
    application_id TEXT NOT NULL,
    scheduled_at TEXT NOT NULL,
    type TEXT
        CHECK (type IS NULL OR type IN ('PHONE', 'VIDEO', 'ONSITE', 'TECHNICAL', 'HR', 'OTHER')),
    interviewer TEXT,
    meeting_url TEXT,
    notes TEXT,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    FOREIGN KEY (application_id) REFERENCES applications(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_interviews_application_scheduled
    ON interviews(application_id, scheduled_at ASC);

CREATE TABLE IF NOT EXISTS notes (
    id TEXT PRIMARY KEY NOT NULL,
    application_id TEXT NOT NULL,
    content TEXT NOT NULL CHECK (length(content) <= 5000),
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    FOREIGN KEY (application_id) REFERENCES applications(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_notes_application_created
    ON notes(application_id, created_at DESC);

CREATE TABLE IF NOT EXISTS reminders (
    id TEXT PRIMARY KEY NOT NULL,
    application_id TEXT NOT NULL,
    title TEXT NOT NULL,
    remind_at TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    FOREIGN KEY (application_id) REFERENCES applications(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_reminders_application_date
    ON reminders(application_id, remind_at ASC);

CREATE INDEX IF NOT EXISTS idx_reminders_application_completed
    ON reminders(application_id, completed);
